import{_ as t,o as e,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-24（地球科学 / 深部生物圈 / 产甲烷古菌）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/science-daily-2026-10-24-earth.md","filePath":"topics/earth-science/science-daily-2026-10-24-earth.md"}'),n={name:"topics/earth-science/science-daily-2026-10-24-earth.md"};function c(i,o,a,g,d,l){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-24-地球科学-深部生物圈-产甲烷古菌" tabindex="-1">科学日报 · 2026-10-24（地球科学 / 深部生物圈 / 产甲烷古菌） <a class="header-anchor" href="#科学日报-·-2026-10-24-地球科学-深部生物圈-产甲烷古菌" aria-label="Permalink to &quot;科学日报 · 2026-10-24（地球科学 / 深部生物圈 / 产甲烷古菌）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> — 第43期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-earth</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-24-一种古菌「独自吃脂肪酸产甲烷」——纯培养证据挑战经典互营范式" tabindex="-1">科学日报 2026-10-24：一种古菌「独自吃脂肪酸产甲烷」——纯培养证据挑战经典互营范式 <a class="header-anchor" href="#科学日报-2026-10-24-一种古菌「独自吃脂肪酸产甲烷」——纯培养证据挑战经典互营范式" aria-label="Permalink to &quot;科学日报 2026-10-24：一种古菌「独自吃脂肪酸产甲烷」——纯培养证据挑战经典互营范式&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1038/s41586-026-11207-x</p></blockquote><ul><li>被挑战的范式（<strong>互营 syntrophy</strong>）：深部生物圈把复杂有机物厌氧降解为 <strong>CH₄ + CO₂</strong>，长期被认为<strong>必须多菌协作</strong> —— <strong>产甲烷古菌只负责终端步骤，只吃简单的 C1/C2 底物</strong>（CO₂/H₂、乙酸、甲醇等），复杂底物的水解/发酵/β-氧化由伙伴微生物完成。</li><li>此前只有间接证据：<strong>热力学论证、多组学、微宇宙实验</strong>都提示某些古菌谱系<strong>可能</strong>直接降解复杂底物，但<strong>缺纯培养验证</strong>（这是关键的「缺环」）。</li><li>本篇：从<strong>中国某油田</strong>分离出嗜热古菌 <strong>Methanoglobus dolicholipophagus AA-75</strong>（属 <strong>Archaeoglobi</strong>）。 <ul><li>能把<strong>甲醇</strong>转化为 <strong>CH₄ + CO₂ + 乙酸</strong>；</li><li>也能直接用<strong>饱和脂肪酸 C7:0 → C18:0</strong> 以及<strong>不饱和脂肪酸 C16:1 / C18:1 / C18:2</strong> 产甲烷。</li></ul></li><li>新命名与机制：作者称之为 <strong>「脂养产甲烷（lipotrophic methanogenesis）」</strong> —— 把 <strong>脂肪酸 β-氧化</strong>、<strong>Wood–Ljungdahl 途径</strong>、经典的 <strong>Mtr（甲基-H₄MPT:CoM 甲基转移酶）/ Mcr（甲基-CoM 还原酶）</strong> 复合体，以及一套<strong>胞内电子传递系统</strong>整合在一起；另有一个<strong>甲醛–甲醇分支</strong>，疑为产甲烷期 C1 代谢的辅助路线。</li><li>同位素指纹（关键的可识别特征）：由<strong>硬脂酸</strong>产生的甲烷 <strong>δ¹³C-CH₄ = −40.0‰ 至 −36.3‰</strong>（<strong>中等 ¹³C 富集</strong>），<strong>明显区别于经典产甲烷途径的强 ¹³C 亏损</strong> → 深海/深部碳循环的<strong>同位素模型需要新增一个端元</strong>。</li><li>洞察（对本库 <code>earth-science</code> × <code>biomedicine</code>）：本条是**「范式被一个纯培养实验推翻」<strong>的教科书式案例，值钱之处在于</strong>证伪所需的证据等级被明确写出**：不是更多组学、不是更多热力学计算，而是<strong>一株菌、一个纯培养</strong>。这给外脑一条可迁移判据——<strong>「当一类结论长期依赖『间接/相关性』证据，要推翻它只需提供一个『直接/单因素』实验」</strong>；反过来，<strong>当你想固化一个结论，先问它的证据等级够不够</strong>。同族对照：库内「端粒酶式逆转录抗病毒（10-13）」「无交换有性生殖（09-21）」都是<strong>用纯培养/单体系把『应该不可能』变成『已观测』</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/earth-science/index.md</code> ｜ 第43期 科学板块</p></blockquote><p>关键词：互营 syntrophy、产甲烷古菌、Methanoglobus dolicholipophagus AA-75、Archaeoglobi、中国油田、嗜热古菌、脂养产甲烷、β-氧化、Wood-Ljungdahl、Mtr、Mcr、甲基-CoM 还原酶、胞内电子传递、甲醛-甲醇分支、硬脂酸 δ13C-CH4 -40.0 至 -36.3 千分号、中等 13C 富集对比经典强亏损、深部生物圈碳循环、纯培养推翻范式、证据等级</p><p>关联：<code>topics/earth-science/science-daily-2026-10-22-earth.md</code>、<code>topics/earth-science/science-daily-2026-10-21-earth.md</code>、<code>topics/biomedicine/index.md</code>、<code>topics/earth-science/index.md</code></p>',10)])])}const u=t(n,[["render",c]]);export{p as __pageData,u as default};
